using System.Collections.Immutable;
using Aict.Core;
using Aict.Beta;
using Aict.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public class MultiQuotaTests {
    static QuotaSlot Slot(int start,int end,int minutes,string name="")=>new(Guid.NewGuid(),start,end,TimeSpan.FromMinutes(minutes),name);
    [TestMethod] public void MergingSlotsCarriesTheCombinedUsageInsteadOfOnlyTheLargestCounter(){var a=Slot(540,720,20);var b=Slot(1080,1320,40);var g=Group(a,b);var l=new UsageLedger().Put(g.Id,new(2026,11,2),new(TimeSpan.FromMinutes(10).Ticks),a.Id).Put(g.Id,new(2026,11,2),new(TimeSpan.FromMinutes(15).Ticks),b.Id);var merged=g with{QuotaSlots=[Slot(540,1320,60)]};var next=QuotaPeriods.CarryForward(Samples.Policy(g),Samples.Policy(merged),l,Samples.At(2,19));Assert.AreEqual(TimeSpan.FromMinutes(25).Ticks,next.Get(g.Id,new(2026,11,2),merged.QuotaSlots!.Value[0].Id).KnownTicks);}
    [TestMethod] public void ConvertingOvernightSlotToDailyKeepsItsPreviousStartDateUsage(){var night=Slot(1320,120,20);var g=Group(night);var l=new UsageLedger().Put(g.Id,new(2026,11,2),new(TimeSpan.FromMinutes(10).Ticks),night.Id);var daily=g with{QuotaSlots=null,DailyQuota=TimeSpan.FromMinutes(30)};var next=QuotaPeriods.CarryForward(Samples.Policy(g),Samples.Policy(daily),l,Samples.At(3,9));Assert.AreEqual(TimeSpan.FromMinutes(10).Ticks,next.Get(g.Id,new(2026,11,3)).KnownTicks);}
    static RuleGroup Group(params QuotaSlot[] slots)=>Samples.Quota() with{DailyQuota=null,DailyQuotaWindow=null,QuotaSlots=slots.ToImmutableArray()};
    static bool Blocked(RuleGroup g,UsageLedger l,DateTimeOffset at)=>RuleEngine.Evaluate(Samples.Policy(g),l,new("app.video"),new(at)).Blocked;
    static UsageLedger Account(RuleGroup g,UsageLedger l,int day,int hour,int minute,int seconds=60)=>RuleEngine.Account(Samples.Policy(g),l,new(Samples.At(day,hour,minute),TimeSpan.FromSeconds(seconds),new("app.video","video.example")));
    [TestMethod] public void MorningAndEveningHaveIndependentLimitsAndResetIndependently(){var a=Slot(540,720,1,"上午");var b=Slot(1080,1320,2,"晚上");var g=Group(a,b);var l=Account(g,new(),2,9,0);Assert.IsTrue(Blocked(g,l,Samples.At(2,9,1)));Assert.IsFalse(Blocked(g,l,Samples.At(2,18)));l=Account(g,l,2,18,0);Assert.IsFalse(Blocked(g,l,Samples.At(2,18,1)));Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,l.Get(g.Id,new(2026,11,2),a.Id).KnownTicks);Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,l.Get(g.Id,new(2026,11,2),b.Id).KnownTicks);l=Account(g,l,2,18,1);Assert.IsTrue(Blocked(g,l,Samples.At(2,18,2)));Assert.IsFalse(Blocked(g,l,Samples.At(2,22)));Assert.IsFalse(Blocked(g,l,Samples.At(3,9)));Assert.IsFalse(Blocked(g,l,Samples.At(3,18)));}
    [TestMethod] public void AdjacentBoundarySliceIsSplitBetweenAccountsWithoutDoubleCounting(){var a=Slot(540,600,1);var b=Slot(600,660,2);var g=Group(a,b);var l=RuleEngine.Account(Samples.Policy(g),new(),new(Samples.At(2,9,59,30),TimeSpan.FromSeconds(60),new("app.video","video.example")));Assert.AreEqual(TimeSpan.FromSeconds(30).Ticks,l.Get(g.Id,new(2026,11,2),a.Id).KnownTicks);Assert.AreEqual(TimeSpan.FromSeconds(30).Ticks,l.Get(g.Id,new(2026,11,2),b.Id).KnownTicks);Assert.AreEqual(2,l.Accounts.Count);}
    [TestMethod] public void AGapOnlyAffectsItsOwnSlot(){var a=Slot(540,720,1);var b=Slot(1080,1320,2);var g=Group(a,b);var l=RuleEngine.Account(Samples.Policy(g),new(),new(Samples.At(2,9),TimeSpan.FromMinutes(1),new("app.video"),ObservationKnown:false));Assert.IsTrue(l.Get(g.Id,new(2026,11,2),a.Id).HasGap);Assert.IsFalse(l.Get(g.Id,new(2026,11,2),b.Id).HasGap);Assert.IsTrue(Blocked(g,l,Samples.At(2,10)));Assert.IsFalse(Blocked(g,l,Samples.At(2,18)));}
    [TestMethod] public void OvernightSlotUsesItsStartingDateWithoutContaminatingMorning(){var night=Slot(1320,120,1);var morning=Slot(540,720,5);var g=Group(night,morning);var l=RuleEngine.Account(Samples.Policy(g),new(),new(Samples.At(2,23,59,30),TimeSpan.FromSeconds(60),new("app.video")));Assert.IsTrue(Blocked(g,l,Samples.At(3,1)));Assert.IsFalse(Blocked(g,l,Samples.At(3,9)));Assert.IsFalse(Blocked(g,l,Samples.At(3,22)));Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,l.Get(g.Id,new(2026,11,2),night.Id).KnownTicks);}
    [TestMethod] public void OverlapValidationIncludesMidnightAndAllowsAdjacentSlots(){foreach(var slots in new[]{new[]{Slot(540,720,1),Slot(600,800,2)},new[]{Slot(1320,120,1),Slot(60,180,2)}})Assert.ThrowsExactly<ArgumentException>(()=>PolicyValidation.Validate(Samples.Policy(Group(slots))));PolicyValidation.Validate(Samples.Policy(Group(Slot(1320,120,1),Slot(120,180,2))));Assert.ThrowsExactly<ArgumentException>(()=>PolicyValidation.Validate(Samples.Policy(Group(Slot(0,1440,1),Slot(100,200,1)))));}
    [TestMethod] public void InvalidSlotIdsMixedModesAndEmptySetsAreRejected(){var s=Slot(540,720,1);foreach(var g in new[]{Group(),Group(s,s),Group(s with{Id=Guid.Empty}),Group(s) with{DailyQuota=TimeSpan.FromMinutes(30)},Group(s with{Name=new string('a',61)})})Assert.ThrowsExactly<ArgumentException>(()=>PolicyValidation.Validate(Samples.Policy(g)));}
    [TestMethod] public void AddingASeparateSlotTightensWhileRemovingOrRaisingOneWaits(){var a=Slot(540,720,20);var b=Slot(1080,1320,40);var g=Group(a);var p=Samples.Policy(g);var now=Samples.At(2,10);var q=p with{Groups=[g with{QuotaSlots=[a,b]}]};Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,q,now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(q,p,now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,p with{Groups=[g with{QuotaSlots=[a with{Limit=TimeSpan.FromMinutes(21)}]}]},now));Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,p with{Groups=[g with{QuotaSlots=[a with{Name="新名称",Limit=TimeSpan.FromMinutes(19)}]}]},now));}
    [TestMethod] public void ConvertingLegacyWindowCarriesItsUsageOnlyToMatchingSlot(){var legacy=Samples.Quota() with{DailyQuotaWindow=new(540,720)};var first=new QuotaSlot(QuotaSchedules.LegacySlotId(legacy.Id),540,720,TimeSpan.FromMinutes(1));var second=Slot(1080,1320,2);var multi=legacy with{DailyQuota=null,DailyQuotaWindow=null,QuotaSlots=[first,second]};var l=new UsageLedger().Put(legacy.Id,new(2026,11,2),new(TimeSpan.FromSeconds(45).Ticks,true));var next=QuotaPeriods.CarryForward(Samples.Policy(legacy),Samples.Policy(multi),l,Samples.At(2,10));Assert.AreEqual(TimeSpan.FromSeconds(45).Ticks,next.Get(legacy.Id,new(2026,11,2),first.Id).KnownTicks);Assert.IsTrue(next.Get(legacy.Id,new(2026,11,2),first.Id).HasGap);Assert.AreEqual(0L,next.Get(legacy.Id,new(2026,11,2),second.Id).KnownTicks);Assert.IsFalse(next.Get(legacy.Id,new(2026,11,2),second.Id).HasGap);Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Samples.Policy(legacy),Samples.Policy(multi),Samples.At(2,10)));}
    [TestMethod] public void RecreatedSlotCannotResetUsageAndEditingOneLeavesOtherAccountAlone(){var a=Slot(540,720,1);var b=Slot(1080,1320,2);var g=Group(a,b);var l=Account(g,new(),2,9,0);l=Account(g,l,2,18,0);var changed=g with{QuotaSlots=[a with{Id=Guid.NewGuid()},b]};var next=QuotaPeriods.CarryForward(Samples.Policy(g),Samples.Policy(changed),l,Samples.At(2,18));Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,next.Get(g.Id,new(2026,11,2),changed.QuotaSlots!.Value[0].Id).KnownTicks);Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,next.Get(g.Id,new(2026,11,2),b.Id).KnownTicks);}
    [TestMethod] public void SlotAccountsSurviveStorageAndExportKeepsSeparateIds(){var a=Slot(540,720,1,"上午");var b=Slot(1080,1320,2,"晚上");var g=Group(a,b);var l=Account(g,new(),2,9,0);l=Account(g,l,2,18,0);string dir=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")??Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string db=Path.Combine(dir,"engine.sqlite");StateRepository.CreateNew(db,new(){Policy=Samples.Policy(g),Usage=l,Clock=new(Samples.At(2,19),true)});var saved=StateRepository.OpenExisting(db).Read().Snapshot;Assert.AreEqual(2,saved.Policy.Groups[0].QuotaSlots!.Value.Length);Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,saved.Usage.Get(g.Id,new(2026,11,2),b.Id).KnownTicks);string csv=UsageExport.ToCsv(saved.Policy,saved.Usage);StringAssert.Contains(csv,a.Id.ToString("N"));StringAssert.Contains(csv,b.Id.ToString("N"));StringAssert.Contains(csv,"上午");StringAssert.Contains(csv,"晚上");}
    [TestMethod] public void DelayedLimitIncreaseKeepsOtherSlotAndOriginalUsage(){var a=Slot(540,720,1);var b=Slot(1080,1320,2);var g=Group(a,b);var p=Samples.Policy(g) with{ChangeDelay=TimeSpan.FromSeconds(10)};var target=p with{Groups=[g with{QuotaSlots=[a with{Limit=TimeSpan.FromMinutes(2)},b]}]};var now=Samples.At(2,10);var old=Account(g,new(),2,9,0);var state=ChangeQueue.Submit(new(){Policy=p,Usage=old,Clock=new(now,true)},target,new(now,true));state=state with{Pending=state.Pending! with{ApplyAtDeadline=true}};Assert.AreEqual(ApplyStatus.WaitingForDelay,ChangeQueue.TryApply(state,new(now.AddSeconds(9),true)).Status);var result=ChangeQueue.TryApply(state,new(now.AddSeconds(10),true));Assert.AreEqual(ApplyStatus.Applied,result.Status);Assert.AreEqual(TimeSpan.FromMinutes(1).Ticks,result.Snapshot.Usage.Get(g.Id,new(2026,11,2),a.Id).KnownTicks);Assert.AreEqual(TimeSpan.FromMinutes(2),result.Snapshot.Policy.Groups[0].QuotaSlots!.Value[1].Limit);}
}
